"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[11124],{56125:e=>{e.exports=JSON.parse('{"tag":{"label":"Orchestrations","permalink":"/docs/tags/orchestrations","allTagsPath":"/docs/tags","count":10,"items":[{"id":"Lakehouse/Orchestrations/Adding members to an orchestration","title":"Adding members to an orchestration","description":"You can add users to an orchestration. If they do not already have access to associated pipelines, they can be granted permissions. Only Lakehouse members can be added, and they will receive creator permissions by default.","permalink":"/docs/Lakehouse/Orchestrations/adding-members-to-orchestration"},{"id":"Lakehouse/Orchestrations/Creating orchestrations","title":"Creating orchestrations","description":"Orchestration in DataGOL allows you to define and manage the execution order of multiple pipelines. This is crucial when you have dependencies between pipelines, where one pipeline needs to complete successfully before another can begin. Without orchestration, scheduling pipelines to run independently might lead to failures or unexpected results if a dependent pipeline runs before its required data is ready.","permalink":"/docs/Lakehouse/Orchestrations/creating-orchestration"},{"id":"Lakehouse/Orchestrations/Deleting an orchestration","title":"Deleting an orchestration","description":"To delete an orchestration, do the following:","permalink":"/docs/Lakehouse/Orchestrations/deleting-an-orchestration"},{"id":"Lakehouse/Orchestrations/Editing an orchestration","title":"Editing an orchestration","description":"To edit an orchestration, do the following:","permalink":"/docs/Lakehouse/Orchestrations/editing-an-orchestration"},{"id":"Lakehouse/Orchestrations/Managing orchestrations","title":"Managing orchestrations","description":"You can manage and monitor the orchestrations from the Orchestrations page. The main Orchestration page display a list of all created orchestrations.","permalink":"/docs/Lakehouse/Orchestrations/managing-orchestration"},{"id":"Lakehouse/Orchestrations/Running an orchestration","title":"Running an orchestration","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration. The list of created orchestrations is displayed.","permalink":"/docs/Lakehouse/Orchestrations/running-an-orchestration"},{"id":"Lakehouse/Orchestrations/Updating the orchestration settings","title":"Updating the orchestration settings","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration.","permalink":"/docs/Lakehouse/Orchestrations/updating-the-orchestration-settings"},{"id":"Lakehouse/Orchestrations/Viewing pipeline details of an orchestration","title":"Viewing pipeline details of an orchestration","description":"From the Pipelines tab of an orchestration, you can view the specifics of each pipeline within an orchestration. Click a pipeline link to access its comprehensive details, including its data source and destination. Furthermore, you can find information about the pipeline\'s creator and its designated stage order. For granular insights, the status and job stage details are readily available. To explore the data lineage, scroll right and click the more options icon.","permalink":"/docs/Lakehouse/Orchestrations/viewing-pipeline-details-of-an-orchestration"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration graph","title":"Viewing the orchestration graph","description":"The Graphs tab within an orchestration provides a clear visual representation of the pipeline\'s execution order, illustrating the sequence of stages. To view the orchestration graph do the following:","permalink":"/docs/Lakehouse/Orchestrations/viewing-the-orchestration-graph"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration run details","title":"Viewing the orchestration run details","description":"The Runs tab provides a comprehensive view of each orchestration execution. Here, you can readily see details such as the run\'s name, the user who initiated it, the start and end times, the total duration, and the current status (e.g., completed, failed). To investigate data lineage, click the more options icon. Additionally, clicking the View Snapshot link offers a detailed, point-in-time overview of that specific run.","permalink":"/docs/Lakehouse/Orchestrations/viewing-the-orchestration-run-details"}],"unlisted":false}}')}}]);